import{_ as a,o,c as t,a3 as r}from"./chunks/framework.CJlOecQn.js";const u=JSON.parse('{"title":"Education and schools","description":"How expat families find and register for public and private schools in Qatar, including who can enrol, what to bring, school fees and the school calendar.","frontmatter":{"title":"Education and schools","description":"How expat families find and register for public and private schools in Qatar, including who can enrol, what to bring, school fees and the school calendar.","lastChecked":"2026-10","sourceCount":9},"headers":[],"relativePath":"guide/education.md","filePath":"guide/education.md"}'),n={name:"guide/education.md"};function s(i,e,f,l,c,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="education-and-schools" tabindex="-1">Education and schools <a class="header-anchor" href="#education-and-schools" aria-label="Permalink to &quot;Education and schools&quot;">​</a></h1><p>Qatar has government (public) schools and private schools, both overseen by the Ministry of Education and Higher Education (MOEHE). Public school places are limited to certain groups, so check whether your child qualifies first.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></p><p>The ministry&#39;s general contact numbers are 155 and 4404 4444.<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1]</a></sup></p><h2 id="who-can-enrol-in-public-schools" tabindex="-1">Who can enrol in public schools <a class="header-anchor" href="#who-can-enrol-in-public-schools" aria-label="Permalink to &quot;Who can enrol in public schools&quot;">​</a></h2><p>MOEHE lists these groups:<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1]</a></sup></p><ul><li>Children of Qatari men and women, and of GCC citizens.<sup class="footnote-ref"><a href="#fn1" id="fnref1:3">[1]</a></sup></li><li>Children of residents working in government sectors.<sup class="footnote-ref"><a href="#fn1" id="fnref1:4">[1]</a></sup></li><li>Children of employees of private charitable institutions.<sup class="footnote-ref"><a href="#fn1" id="fnref1:5">[1]</a></sup></li><li>Children of permanent residency holders.<sup class="footnote-ref"><a href="#fn1" id="fnref1:6">[1]</a></sup></li></ul><p>Children of residents working in the private sector have a narrower route: 18 schools in outlying areas and villages are set aside for them. You need proof that you really live there, such as a notarised lease or an electricity certificate in the guardian&#39;s name.<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup> Non-Arabic speakers in this group must pass an Arabic test and may be placed in a remedial Arabic programme, and a later transfer to a government school in Doha or another urban area is not allowed.<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></p><h2 id="how-to-register-for-a-public-school" tabindex="-1">How to register for a public school <a class="header-anchor" href="#how-to-register-for-a-public-school" aria-label="Permalink to &quot;How to register for a public school&quot;">​</a></h2><ol><li>Use the &quot;Where Is My School?&quot; system to find the school that fits your home address.<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2]</a></sup></li><li>Log in to the Maaref portal and choose the public school registration service.<sup class="footnote-ref"><a href="#fn1" id="fnref1:7">[1]</a></sup></li><li>If the system is closed, apply manually at a school in your area. Acceptance depends on free places.<sup class="footnote-ref"><a href="#fn1" id="fnref1:8">[1]</a></sup></li></ol><p>Have these ready: the child&#39;s Qatari ID card, birth certificate and health file. Children of residents also need a certificate of employment.<sup class="footnote-ref"><a href="#fn2" id="fnref2:2">[2]</a></sup></p><p>For 2026 to 2027, registration opened to all nationalities from 24 May 2026 and reopened from 25 August to 1 October 2026. Age was counted as of 31 December 2026, and Grade 1 was open to children born on or before 31 December 2020.<sup class="footnote-ref"><a href="#fn2" id="fnref2:3">[2]</a></sup> Those dates apply to that year only, so look for the ministry&#39;s circular for the next one.<sup class="footnote-ref"><a href="#fn2" id="fnref2:4">[2]</a></sup></p><h2 id="how-to-register-for-a-private-school" tabindex="-1">How to register for a private school <a class="header-anchor" href="#how-to-register-for-a-private-school" aria-label="Permalink to &quot;How to register for a private school&quot;">​</a></h2><ol><li>Search the ministry&#39;s interactive map of private schools and kindergartens.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup></li><li>Contact the school directly, because each school runs registration under its own policy.<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup></li><li>If you hit a problem, the Private School Licensing Department can help you register or find another school.<sup class="footnote-ref"><a href="#fn5" id="fnref5:1">[5]</a></sup></li></ol><h2 id="children-arriving-on-a-family-visa" tabindex="-1">Children arriving on a family visa <a class="header-anchor" href="#children-arriving-on-a-family-visa" aria-label="Permalink to &quot;Children arriving on a family visa&quot;">​</a></h2><p>MOEHE runs a Mandatory Education Platform for children aged 6 to 18 who hold a family visa convertible to residency. Through it you can apply to a private school, apply to a government school, or show that the child is studying outside Qatar or has a valid medical reason for not studying.<sup class="footnote-ref"><a href="#fn3" id="fnref3:1">[3]</a></sup></p><ul><li>Each child needs a separate application, and you can submit only one at a time. If it is rejected, you can apply to a different school.<sup class="footnote-ref"><a href="#fn3" id="fnref3:2">[3]</a></sup></li><li>The system shows only schools with free seats, with links to their websites so you can check tuition fees and conditions.<sup class="footnote-ref"><a href="#fn3" id="fnref3:3">[3]</a></sup></li><li>After review, the school contacts you for an interview, and you may have to pay registration fees under its policy.<sup class="footnote-ref"><a href="#fn3" id="fnref3:4">[3]</a></sup></li><li>International schools need an officially approved certificate for the last grade completed. Schools following Qatar&#39;s national standards send you to the Student Information Center for a certificate equivalency first.<sup class="footnote-ref"><a href="#fn3" id="fnref3:5">[3]</a></sup></li><li>After the child gets a QID, transfers between curricula are allowed until the end of January, and within the same curriculum until the end of February.<sup class="footnote-ref"><a href="#fn3" id="fnref3:6">[3]</a></sup></li></ul><p>Parents working in the government sector do not use this platform, because the ministry handles their registration based on vacancies and admission criteria.<sup class="footnote-ref"><a href="#fn3" id="fnref3:7">[3]</a></sup></p><h2 id="school-fees" tabindex="-1">School fees <a class="header-anchor" href="#school-fees" aria-label="Permalink to &quot;School fees&quot;">​</a></h2><p>MOEHE has issued a Private Schools and Kindergartens Fees Policy that binds all private schools and kindergartens. It aims to make sure approved fees are disclosed and to stop schools collecting fees the ministry has not approved in advance.<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup></p><p>Operational, service and optional fees also need prior approval and must be clearly disclosed. Parents do not have to pay optional fees.<sup class="footnote-ref"><a href="#fn6" id="fnref6:1">[6]</a></sup> Ask the school to show you its approved fees before you pay.<sup class="footnote-ref"><a href="#fn6" id="fnref6:2">[6]</a></sup></p><h2 id="school-calendar" tabindex="-1">School calendar <a class="header-anchor" href="#school-calendar" aria-label="Permalink to &quot;School calendar&quot;">​</a></h2><p>The 2026 to 2027 school year started on Sunday 30 August 2026.<sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup> MOEHE publishes the annual calendar for each year, with holidays and test dates for state schools.<sup class="footnote-ref"><a href="#fn8" id="fnref8">[8]</a></sup> The approved calendar for 2025 to 2028 fixes the mid-year break in the last third of December, and the announcement says this helps line up public and private school holidays.<sup class="footnote-ref"><a href="#fn9" id="fnref9">[9]</a></sup></p><p>See also: <a href="./family-visas">Family visas</a>, <a href="./residence-permit-and-qid">Residence permit and QID</a>.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>Ministry of Education and Higher Education, <a href="https://www.edu.gov.qa/en/Content/RegistrationPublicShools" target="_blank" rel="noreferrer">Registration in public Schools</a>. Last checked: 2026-10. <a href="#fnref1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:7" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:8" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn2" class="footnote-item"><p>Ministry of Education and Higher Education, <a href="https://www.edu.gov.qa/en/News/Details/17391000" target="_blank" rel="noreferrer">Circular on Student Registration and Transfer Procedures for the 2026 to 2027 Academic Year</a>. Last checked: 2026-10. <a href="#fnref2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:4" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn3" class="footnote-item"><p>Ministry of Education and Higher Education, <a href="https://www.edu.gov.qa/en/Content/CompulsoryEducationVisas" target="_blank" rel="noreferrer">Compulsory Education (Visas)</a>. Last checked: 2026-10. <a href="#fnref3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:7" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn4" class="footnote-item"><p>Ministry of Education and Higher Education, <a href="https://www.edu.gov.qa/en/Content/Listofprivateschools" target="_blank" rel="noreferrer">List of private schools and kindergartens</a>. Last checked: 2026-10. <a href="#fnref4" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn5" class="footnote-item"><p>Ministry of Education and Higher Education, <a href="https://www.edu.gov.qa/en/Content/RegistrationPrivateSchool" target="_blank" rel="noreferrer">Registration in Private School</a>. Last checked: 2026-10. <a href="#fnref5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:1" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn6" class="footnote-item"><p>Ministry of Education and Higher Education, <a href="https://www.edu.gov.qa/en/News/Details/18451800" target="_blank" rel="noreferrer">Education Ministry Launches Private Schools and Kindergartens Fees Policy</a>. Last checked: 2026-10. <a href="#fnref6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref6:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref6:2" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn7" class="footnote-item"><p>Ministry of Education and Higher Education, <a href="https://www.edu.gov.qa/en/News/Details/19063800" target="_blank" rel="noreferrer">Education Ministry Announces the Completion of its Preparations for the New School Year</a>. Last checked: 2026-10. <a href="#fnref7" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn8" class="footnote-item"><p>Ministry of Education and Higher Education, <a href="https://www.edu.gov.qa/en/Content/AnnualCalendar" target="_blank" rel="noreferrer">Annual Calendar</a>. Last checked: 2026-10. <a href="#fnref8" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn9" class="footnote-item"><p>Ministry of Education and Higher Education, <a href="https://www.edu.gov.qa/ar/News/Details/14514600" target="_blank" rel="noreferrer">New academic calendar for 2025 to 2028 (in Arabic)</a>. Last checked: 2026-10. <a href="#fnref9" class="footnote-backref" aria-label="Back to text">↑</a></p></li></ol></section>',26)])])}const p=a(n,[["render",s]]);export{u as __pageData,p as default};
